var t=`0308-shopska-salata`;var n=`world-0308`;var a=`BG`;var s=`eastern-europe`;var r=4;var o=13;var l={en:`Shopska Salata`,ua:`Шопський салат`};var g={en:`A traditional Bulgaria dish made with tomato, cucumber, green bell pepper, red onion. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Болгарія. Основні інгредієнти: помідор, огірок, зелений солодкий перець, червона цибуля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:8,i:[[`tomato`,400,`g`],[`cucumber`,310,`g`],[`green-bell-pepper`,200,`g`],[`red-onion`,100,`g`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:3,i:[[`extra-virgin-olive-oil`,55,`ml`],[`white-wine-vinegar`,22,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`feta`,220,`g`]]}];var p={slug:t,id:n,country:`BG`,region:s,servings:4,minutes:13,title:l,text:g,steps:d};export{a as country,p as default,n as id,o as minutes,s as region,r as servings,t as slug,d as steps,g as text,l as title};